import lib
PF='https://profi.ru/geo-krsk/remont/'
U=lambda oid: lib.ORG[oid]['url']
N=lambda oid: lib.ORG[oid]['meta']['title']
def P(oid,rx,ex=None):
    for x in lib.ORG[oid]['items']:
        if re.search(rx,x['title'] or '',re.I) and not (ex and re.search(ex,x['title'],re.I)) and (lib._num(x['price']) or 0)>1: return x['title'].strip(),lib._num(x['price'])
    raise SystemExit(f'нет {oid} {rx}')
def MEDI(oid,rx,ex,minp):
    v=[lib._num(x['price']) for x in lib.ORG[oid]['items'] if re.search(rx,x['title'],re.I) and not re.search(ex,x['title'],re.I) and (lib._num(x['price']) or 0)>minp]
    return statistics.median(v),len(v),min(v),max(v)
def combo(oid,parts,note=''):
    """parts: [(title,price)] из одного прайса -> один источник-сумма"""
    return W(N(oid),U(oid),' + '.join(f'{int(p)} ₽' for _,p in parts),' + '.join(t for t,_ in parts)+note,sum(p for _,p in parts))
